def rules():
    out=[]; counts={}
    for line in RULE_TSV.strip().splitlines():
        if not line.strip():continue
        vals=line.strip().split('|'); assert len(vals)==10,(len(vals),line)
        c,title,p,decision,boundary,action,evidence,sources,keys,nature=vals
        counts[c]=counts.get(c,0)+1
        out.append(dict(id=f'{c}-{counts[c]:02d}',category=c,title=title,priority=p,decision=decision,boundary=boundary,action=action,evidence=evidence,sources=sources.split(','),keywords=keys.split(','),nature=nature))
    return out
